static str deepLink_Test()
{
    str retVal;

    // gets the generator instance
    var generator     = new Microsoft.Dynamics.AX.Framework.Utilities.UrlHelper.UrlGenerator();
    var currentHost   = new System.Uri(UrlUtility::getUrl());

    generator.HostUrl = currentHost.GetLeftPart(System.UriPartial::Authority);
    generator.Company = curext();
    generator.MenuItemName = menuItemDisplayStr(AVAKBVBuildingProjectTable);
    generator.Partition = getCurrentPartition();

    var requestQueryParameterCollection = generator.RequestQueryParameterCollection;

    requestQueryParameterCollection.AddRequestQueryParameter(   'KCS_KBVBuildingProjectTable',
                                                                'KCS_KBVBuildingProjectID', 'BV1000095');
    /*
