    return retVal;
}

/// <summary>
///    AVA <c>htmlBreak</c> method.
/// </summary>
/// <param name="_noOfBreaks">
///    <c>int</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlBreak(int _noOfBreaks = 1)
{
    str retVal;
    int counter;

    #define.htmlBreak('<BR>')

    for(counter = 0; counter < _noOfBreaks; counter++)
    {
        retVal += #htmlBreak;
    }

    return retVal;
}

/// <summary>
///    AVA <c>htmlSpace</c> method.
/// </summary>
/// <param name="_noOfSpaces">
///    <c>int</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlSpace(int _noOfSpaces = 1)
{
    str retVal;
    int counter;

    #define.htmlSpace('&nbsp;')

    for(counter = 0; counter < _noOfSpaces; counter++)
    {
        retVal += #htmlSpace;
    }

    return retVal;
}

/// <summary>
///    AVA <c>htmlLink</c> method.
/// </summary>
/// <param name="_url">
///    <c>str</c> as type
/// </param>
/// <param name="_text">
///    <c>str</c> as type
/// </param>
/// <param name="_label">
///    <c>str</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlLink(str _url, str _text, str _label = '')
{
    #define.htmlTarget('_blank')
    #define.htmlBreak('<BR>')

    HtmlTextWriter htmlTxtWriter = new HtmlTextWriter();

    htmlTxtWriter.renderBeginTag(HtmlTextWriterTag::div_tag());
    htmlTxtWriter.write(_label);
    htmlTxtWriter.addAttribute(HtmlTextWriterAttribute::href(), _url);
    htmlTxtWriter.addAttribute(HtmlTextWriterAttribute::target(), #htmlTarget);
    htmlTxtWriter.renderBeginTag(HtmlTextWriterTag::A());
    htmlTxtWriter.write(_text);
    htmlTxtWriter.renderEndTag();
    htmlTxtWriter.renderEndTag();

    return htmlTxtWriter.getHtmlString();
}

/// <summary>
///    AVA <c>htmlTable</c> method.
/// </summary>
/// <param name="_content">
///    <c>str</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlTable(str _content, boolean _addBeginTag = true, boolean _addEndTag = true)
{
    HtmlTextWriter htmlTxtWriter = new HtmlTextWriter();

    #define.htmlBreak('<BR>')

    if(_addBeginTag)
    {
        htmlTxtWriter.renderBeginTag(HtmlTextWriterTag::table());
    }
    htmlTxtWriter.write(_content);
    if(_addEndTag)
    {
        htmlTxtWriter.renderEndTag();
    }

    return htmlTxtWriter.getHtmlString();
}

/// <summary>
///    AVA <c>htmlTableRow</c> method.
/// </summary>
/// <param name="_content">
///    <c>str</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlTableRow(str _content)
{
    HtmlTextWriter htmlTxtWriter = new HtmlTextWriter();

    #define.htmlBreak('<BR>')

    htmlTxtWriter.renderBeginTag(HtmlTextWriterTag::tr());
    htmlTxtWriter.write(_content);
    htmlTxtWriter.renderEndTag();

    return htmlTxtWriter.getHtmlString();
}

/// <summary>
///    AVA <c>htmlTableCell</c> method.
/// </summary>
/// <param name="_content">
///    <c>str</c> as type
/// </param>
/// <param name="_align">
///    <c>str</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str htmlTableCell(str _content, str _align = 'left')
{
    HtmlTextWriter htmlTxtWriter = new HtmlTextWriter();
    str tmpString;

    #define.htmlBreak('<BR>')

    tmpString = _content;
    if(!tmpString)
    {
        tmpString = AVABPHTMLHelper::htmlSpace(1);
    }

    htmlTxtWriter.renderBeginTag(HtmlTextWriterTag::td());
    htmlTxtWriter.write(tmpString);
    htmlTxtWriter.addAttribute(HtmlTextWriterAttribute::align(), _align);   // use stileSheet instead, this do not work for <td>
    htmlTxtWriter.renderEndTag();

    //return htmlTxtWriter.getHtmlString();

    tmpString =  htmlTxtWriter.getHtmlString();
    tmpString = strReplace(tmpString, '<td', '<td  style=' + '"' + 'text-align:' + _align + '"');
    return tmpString;
}

/// <summary>
///    AVA <c>deepLink</c> method.
/// </summary>
/// <param name="_menuItemName">
///    <c>MenuItemName</c> as type
/// </param>
/// <param name="_menuItemtype">
///    <c>MenuItemType</c> as type
/// </param>
/// <param name="_dataSource">
///    <c>DataSourceName</c> as type
/// </param>
/// <param name="_field">
///    <c>FieldName</c> as type
/// </param>
/// <param name="_value">
///    <c>str</c> as type
/// </param>
/// <param name="_encryptRequestQuery">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
private static str deepLink(MenuItemName    _menuItemName,
                            MenuItemType    _menuItemtype,
                            DataSourceName  _dataSource             = '',
                            FieldName       _field                  = '',
                            str             _value                  = '',
                            boolean         _encryptRequestQuery    = true)
{
    System.Uri                          fullURI;

    var         env         = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment();
    str         currentUrl  = env.Infrastructure.HostUrl;
    //var currentHost                     = new System.Uri(UrlUtility::getUrl());  // does not work in batch mode
    System.Uri  currentHost = new System.Uri(currentUrl);
    str         hostUrl     = currentHost.GetLeftPart(System.UriPartial::Authority);

    var generator                       = new Microsoft.Dynamics.AX.Framework.Utilities.UrlHelper.UrlGenerator();
    var requestQueryParameterCollection = new Microsoft.Dynamics.AX.Framework.Utilities.UrlHelper.RequestQueryParameterCollection();

    generator.HostUrl               = hostUrl;
    generator.Company               = curExt();
    generator.MenuItemName          = _menuItemName;
    generator.MenuItemType          = _menuItemtype;
    generator.Partition             = getCurrentPartition();
    generator.EncryptRequestQuery   = _encryptRequestQuery;

    if(_dataSource != '')
    {
        requestQueryParameterCollection = generator.RequestQueryParameterCollection;
        requestQueryParameterCollection.UpdateOrAddEntry(   _dataSource,
                                                            _field, _value);
    }

    fullURI = generator.GenerateFullUrl();

    return fullURI.AbsoluteUri;
}

/// <summary>
///    AVA <c>getEncryptRequestQuery</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
private static boolean getEncryptRequestQuery()
{
    return true;
}

/// <summary>
///    AVA <c>deepLinkBuildingProject</c> method.
/// </summary>
/// <param name="_id">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///    <c>str</c> as return value
/// </returns>
public static str deepLinkBuildingProject(KCS_KBVBuildingProjectID _id)
{
    MenuItemName    locMenuItemName;
    MenuItemType    locMenuItemType;
    DataSourceName  locDataSourceName;
    FieldName       locFieldName;
    boolean         locEncryptRequestQuery;

    locMenuItemName         = menuItemDisplayStr(AVAKBVBuildingProjectTable);
    locMenuItemType         = MenuItemType::Display;
    locDataSourceName       = formDataSourceStr(AVAKBVBuildingProjectTable, KCS_KBVBuildingProjectTable);
    locFieldName            = fieldstr(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID);
    locEncryptRequestQuery  = AVABPHTMLHelper::getEncryptRequestQuery();

    return AVABPHTMLHelper::deepLink(   locMenuItemName,
                                        locMenuItemType,
                                        locDataSourceName,
                                        locFieldName,
                                        _id,
                                        locEncryptRequestQuery  );
}

