/// <summary>
///    AVA <c>sendBPEmail</c> method.
/// </summary>
/// <param name="_emailFrom">
///    <c>Email</c> as type
/// </param>
/// <param name="_emailTo">
///    <c>Email</c> as type
/// </param>
/// <param name="_subject">
///    <c>str</c> as type
/// </param>
/// <param name="_body">
///    <c>str</c> as type
/// </param>
/// <param name="_nonInteractive">
///    <c>boolean</c> as type
/// </param>
/// <param name="_emailSendingActivated">
///    <c>boolean</c> as type
/// </param>
/// <param name="_infoMessageActivated">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean sendBPEmail(Email   _emailFrom,
                    Email   _emailTo,
                    str     _subject,
                    str     _body,
                    boolean _nonInteractive         = true,
                    boolean _emailSendingActivated  = true,
                    boolean _infoMessageActivated   = false)
{
    boolean                 retVal;

    SysMailerMessageBuilder messageBuilder;

    retVal = true;

    if(_emailSendingActivated)
    {
        messageBuilder = new SysMailerMessageBuilder();

        try
        {
            messageBuilder.setBody(_body, true);
            messageBuilder.setSubject(_subject);
            messageBuilder.addTo(_emailTo);
            // Note: not calling setFrom() defaults to the current user for SMTP client, whereas
            // when sent to Outlook any setFrom() value will be ignored since profiles on the client are used
            messageBuilder.setFrom(_emailFrom);

            // Open the generated email in the configured client
            if(_nonInteractive)
            {
                // Try using sendNonInteractive method too
                retVal = SysMailerFactory::sendNonInteractive(messageBuilder.getMessage());
            }
            else
            {
                // Sends a message interactively, allowing the user to view and modify the message before
                retVal = SysMailerFactory::sendInteractive(messageBuilder.getMessage());
            }
        }
        catch (Exception::Error)
        {
            throw error(strFmt("@NDX:NXABPInfoEmailSubjectNotSent", _emailTo + ':' + _subject));
        }
    }
    if(_infoMessageActivated)
    {
        info(strFmt("@NDX:NXAEmailContentInfo", _emailFrom,
                                                _emailTo,
                                                _subject,
                                                _body       )   );
    }

    return retVal;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
static void main(Args _args)
{
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;
    SalesQuotationTable         locSalesQuotationTable;
    KCS_KBVRequestTable         locKCS_KBVRequestTable;
    smmActivities               locsmmActivities;

    str htmlTxt;

    str htmlRows;
    str htmlCells;

    str link;
    str linkText;
    str linkLabel;
    /*
    str htmlLinkStr;

    link        = "https://docs.microsoft.com/en-us/dotnet/api/system.web.ui.htmltextwriter?view=netframework-4.8";
    linkText    = "Framework 4.8";
    linkLabel   = "Link: ";
    htmlLinkStr = AVABPHTMLHelper::htmlLink(link, linkText, linkLabel);


    htmlCells   = '';
    htmlCells   += AVABPHTMLHelper::htmlTableCell(htmlLinkStr);
    htmlCells   += AVABPHTMLHelper::htmlTableCell('12. Spalteninhalt');
    htmlCells   += AVABPHTMLHelper::htmlTableCell('13. Spalteninhalt');

    htmlRows    += AVABPHTMLHelper::htmlTableRow(htmlCells);


    htmlTxt     =  AVABPHTMLHelper::htmlTable(htmlRows);
    info(htmlTxt);
    */

    htmlTxt     = '';
    htmlCells   = '';
    htmlRows    = '';

    select firstonly locKCS_KBVBuildingProjectTable order by locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID desc;
    linkText    = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
    link = AVABPHTMLHelper::deepLinkBuildingProject(linkText);
    linkLabel   = strFmt("@SYS82282" + ': ', "@NDX:NXABuildingProject");
    htmlCells   = '';
    htmlCells   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(link, linkText, linkLabel));
    htmlRows    += AVABPHTMLHelper::htmlTableRow(htmlCells);

    select firstonly locSalesQuotationTable order by locSalesQuotationTable.QuotationId desc;
    linkText    = locSalesQuotationTable.QuotationId;
    link = AVABPHTMLHelper::deepLinkQuotation(linkText);
    linkLabel   = strFmt("@SYS82282" + ': ', "@NDX:NXAQuotations");
    htmlCells   = '';
    htmlCells   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(link, linkText, linkLabel));
    htmlRows    += AVABPHTMLHelper::htmlTableRow(htmlCells);

    select firstonly locKCS_KBVRequestTable order by locKCS_KBVRequestTable.KCS_KBVRequestID desc;
    linkText    = locKCS_KBVRequestTable.KCS_KBVRequestID;
    link = AVABPHTMLHelper::deepLinkRequest(linkText);
    htmlCells   = '';
    linkLabel   = strFmt("@SYS82282" + ': ', "@NDX:NXARequest");
    htmlCells   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(link, linkText, linkLabel));
    htmlRows    += AVABPHTMLHelper::htmlTableRow(htmlCells);

    select firstonly locsmmActivities order by locsmmActivities.ActivityNumber desc;
    linkText    = locsmmActivities.ActivityNumber;
    link = AVABPHTMLHelper::deepLinkSmmActivities(linkText);
    htmlCells   = '';
    linkLabel   = strFmt("@SYS82282" + ': ', "@NDX:NDXActivityName");
    htmlCells   += AVABPHTMLHelper::htmlTableCell(AVABPHTMLHelper::htmlLink(link, linkText, linkLabel));
    htmlRows    += AVABPHTMLHelper::htmlTableRow(htmlCells);

    htmlTxt     = AVABPHTMLHelper::htmlTable(htmlRows);
    htmlTxt     = AVABPHTMLHelper::htmlBreak() + htmlTxt;
    htmlTxt     = AVABPHTMLHelper::htmlBreak() + htmlTxt;

    info(htmlTxt);
}
